    def test_publisher_does_not_pass_a_skipped_browser(
        self,
    ):
        client = FakeGitHub(
            {
                "README.md": (
                    "original\n"
                )
            }
        )

        init(client)

        candidate = handle(
            client,
            patch(client),
            POLICY,
        )["head_sha"]

        job_id = "d" * 32

        client.run = {
            "display_title": (
                f"agent-{job_id}-"
                f"{candidate}"
            ),
            "head_sha": BASE_SHA,
            "event": (
                "workflow_dispatch"
            ),
            "html_url": (
                "https://github.com/"
                "example/run/42"
            ),
            "conclusion": "success",
            "steps": [
                {
                    "name": name,
                    "conclusion": (
                        "skipped"
                        if name
                        == "Strict browser E2E"
                        else "success"
                    ),
                }
                for name in REQUIRED_STEPS
            ],
        }

        report = publish(
            client,
            POLICY,
            {
                "inputs": {
                    "job_id": job_id,
                    "expected_sha": (
                        candidate
                    ),
                    "task_id": TASK_ID,
                }
            },
            BASE_SHA,
            42,
            "success",
        )

        self.assertEqual(
            report["result"],
            "failure",
        )

        self.assertEqual(
            client.checks[-1][
                "conclusion"
            ],
            "failure",
        )

        self.assertEqual(
            client.read_data(
                journal_path(
                    TASK_ID
                )
            )["status"],
            "FIX",
        )

    def test_four_failures_block_corrections(
        self,
    ):
        client = FakeGitHub(
            {
                "README.md": (
                    "original\n"
                )
            }
        )

        init(client)

        old = "original"
        head = BASE_SHA

        for index in range(4):
            new = (
                f"revision-{index}"
            )

            operation = (
                f"{index + 1:032x}"
            )

            head = handle(
                client,
                patch(
                    client,
                    head,
                    old,
                    new,
                    operation,
                ),
                POLICY,
            )["head_sha"]

            job_id = (
                f"{index + 20:032x}"
            )

            client.run = {
                "display_title": (
                    f"agent-{job_id}-"
                    f"{head}"
                ),
                "head_sha": (
                    BASE_SHA
                ),
                "event": (
                    "workflow_dispatch"
                ),
                "html_url": (
                    "https://github.com/"
                    "example/run/42"
                ),
                "conclusion": (
                    "failure"
                ),
                "steps": [
                    {
                        "name": name,
                        "conclusion": (
                            "failure"
                            if name == "Build"
                            else "skipped"
                        ),
                    }
                    for name
                    in REQUIRED_STEPS
                ],
            }

            publish(
                client,
                POLICY,
                {
                    "inputs": {
                        "job_id": (
                            job_id
                        ),
                        "expected_sha": (
                            head
                        ),
                        "task_id": (
                            TASK_ID
                        ),
                    }
                },
                BASE_SHA,
                42,
                "failure",
            )

            old = new

        self.assertEqual(
            client.read_data(
                journal_path(
                    TASK_ID
                )
            )["status"],
            "BLOCKED",
        )

        with self.assertRaisesRegex(
            AgentError,
            "TASK_NOT_EDITABLE",
        ):
            handle(
                client,
                patch(
                    client,
                    head,
                    old,
                    "fifth",
                    "f" * 32,
                ),
                POLICY,
            )


